'use strict';
const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const yen=n=>'¥'+n.toLocaleString('ja-JP');
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const styles=[
 {name:'Soft chestnut',ja:'ソフトチェスナット',mood:'自然体の、柔らかさ。',description:'光を含んだようなチェスナットブラウン。顔まわりのレイヤーと、毛先の柔らかな動きで、飾りすぎない雰囲気に。',color:'#e6ddd0',swatch:'#856144',staff:0},
 {name:'Airy beige',ja:'エアリーベージュ',mood:'軽やかな、抜け感。',description:'くすみを感じるベージュと、すっとまとまるボブ。落ち着いた色味の中に、軽やかさを感じるスタイルです。',color:'#deddd4',swatch:'#a29177',staff:1},
 {name:'Rose brown',ja:'ローズブラウン',mood:'さりげない、華やかさ。',description:'ブラウンに、ほんのりローズのニュアンスを。柔らかなウェーブとともに、いつもの装いに小さなときめきを添えます。',color:'#ead8d0',swatch:'#ac7770',staff:0}
];
const staff=[{name:'Aoi',ja:'アオイ',photo:4,description:'好きな色や服、普段の過ごし方。そんなお話から、あなたの気分に合う髪を一緒に探します。柔らかなカラーと、顔まわりのデザインが得意なスタイリスト、というデモ設定です。'}, {name:'Ren',ja:'レン',photo:5,description:'朝のスタイリングが、少し楽しくなるように。自然なまとまりと、扱いやすいシルエットを大切に。ボブとナチュラルなカットが得意なスタイリスト、というデモ設定です。'}];
const menus=[{name:'カット ＋ カラー',en:'CUT + COLOR',price:12100,time:120,color:true,description:'カウンセリング、カット、カラー、シャンプー・ブロー込み。今の気分に合わせた色とシルエットをご提案。'}, {name:'デザインカット',en:'DESIGN CUT',price:5500,time:60,color:false,description:'カウンセリング、カット、シャンプー・ブロー込み。日々のお手入れに合わせて、心地よい形へ。'}, {name:'カット ＋ パーマ',en:'CUT + PERM',price:13200,time:150,color:false,description:'カットとパーマで、毛先に柔らかな動きを。シャンプー・ブロー込み。'}, {name:'カラー ＋ ケア',en:'COLOR + CARE',price:11000,time:90,color:true,description:'カラーとベーシックケアで、つややかな印象に。シャンプー・ブロー込み。集中トリートメントは別途追加できます。'}];
let selectedMenu=0, selectedStyle=null, selectedStaff=-1;
const getQuote=()=>({price:menus[selectedMenu].price+Number($('#hair-length').value)+($('#treatment').checked?3300:0),time:menus[selectedMenu].time+($('#treatment').checked?20:0)});
function updateQuote(animate=true){const q=getQuote();$('#selected-menu-title').textContent=menus[selectedMenu].name;$('#total-price').textContent=yen(q.price);$('#total-time').textContent='約'+q.time+'分';const visual=$('#selection-visual');if(visual){const changed=visual.dataset.menu!==String(selectedMenu);visual.className='selection-visual menu-image-'+selectedMenu;visual.dataset.menu=String(selectedMenu);$('.selection-visual-label',visual).textContent=menus[selectedMenu].en;if(animate&&changed&&!reduced&&typeof visual.animate==='function'){visual.getAnimations().forEach(a=>a.cancel());visual.animate([{opacity:.35,transform:'scale(.96)'},{opacity:1,transform:'scale(1)'}],{duration:550,easing:'cubic-bezier(.2,.7,.3,1)'});}}if(animate){$('#total-price').classList.remove('price-pop');void $('#total-price').offsetWidth;$('#total-price').classList.add('price-pop');}}
function selectMenu(index,focus=false){selectedMenu=index;renderMenus();updateQuote();if(focus)$('[data-menu="'+index+'"]').focus({preventScroll:true});}
function renderMenus(){ $('#menu-list').innerHTML=menus.map((m,i)=>`<article class="menu-item ${i===selectedMenu?'selected':''}"><button class="menu-choice" role="radio" aria-checked="${i===selectedMenu}" tabindex="${i===selectedMenu?0:-1}" data-menu="${i}"><span class="menu-thumb menu-image-${i}" aria-hidden="true"><span class="menu-photo-index">0${i+1}</span><span class="menu-photo-selected">✓ 選択中</span></span><span class="menu-wording"><span class="menu-radio" aria-hidden="true"></span><span class="menu-name">${m.name}<small>${m.en}</small></span></span><span class="menu-cost">${yen(m.price)}<small>約${m.time}分 / 税込</small></span></button><p class="menu-description" ${i===selectedMenu?'':'hidden'}>${m.description}</p></article>`).join('');$('#menu-list').setAttribute('role','radiogroup');$('#menu-list').setAttribute('aria-label','施術メニュー');$$('[data-menu]').forEach(b=>{b.onclick=()=>selectMenu(Number(b.dataset.menu),true);b.onkeydown=e=>{const index=Number(b.dataset.menu);let next;if(e.key==='ArrowDown'||e.key==='ArrowRight')next=(index+1)%menus.length;else if(e.key==='ArrowUp'||e.key==='ArrowLeft')next=(index+menus.length-1)%menus.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=menus.length-1;else return;e.preventDefault();selectMenu(next,true);};});}
renderMenus();updateQuote(false);$('#hair-length').onchange=()=>updateQuote();$('#treatment').onchange=()=>updateQuote();
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800);}
function openDialog(dialog){dialog.showModal();document.body.classList.add('modal-open');}
$$('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>{d.addEventListener('close',()=>document.body.classList.remove('modal-open'));d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});});
function showStyle(i){const s=styles[i];$('#detail-content').innerHTML=`<div class="detail-layout"><div class="photo p${i}" role="img" aria-label="${s.ja}の参考イメージ"></div><div class="detail-copy"><p class="eyebrow">STYLE ${String(i+1).padStart(2,'0')}</p><h2>${s.name}</h2><p>${s.description}</p><p>おすすめ：カット ＋ カラー<br>担当イメージ：${staff[s.staff].name}<br>基本料金 ${yen(menus[0].price)} / 約120分</p><button class="button dark" id="style-select">このスタイルで相談する <span>↗</span></button><small>AI生成の参考写真です。仕上がりは髪の状態などで異なります。</small></div></div>`;openDialog($('#detail-dialog'));$('#style-select').onclick=()=>{selectedStyle=i;selectedStaff=s.staff;selectedMenu=0;$('#hair-length').value=i===1?'0':'2200';renderMenus();updateQuote();$('#detail-dialog').close();toast(s.ja+'を予約内容に追加しました');openBooking();};}
$$('[data-style]').forEach(b=>b.onclick=()=>showStyle(Number(b.dataset.style)));
$$('[data-filter]').forEach(b=>b.onclick=()=>{$$('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});$$('.style-card').forEach(c=>c.hidden=b.dataset.filter!=='all'&&c.dataset.length!==b.dataset.filter);$('#style-gallery').scrollLeft=0;});
function scrollGallery(direction){$('#style-gallery').scrollBy({left:direction*($('#style-gallery .style-card:not([hidden])').getBoundingClientRect().width+20),behavior:reduced?'auto':'smooth'});}$('#gallery-prev').onclick=()=>scrollGallery(-1);$('#gallery-next').onclick=()=>scrollGallery(1);
$('#motion-toggle').onclick=()=>{let paused=document.body.classList.toggle('motion-paused');$('#motion-toggle').setAttribute('aria-pressed',String(paused));$('#motion-toggle').setAttribute('aria-label',paused?'写真の動きを再開':'写真の動きを停止');$('#motion-toggle').textContent=paused?'▷':'Ⅱ';};if(reduced){$('#motion-toggle').hidden=true;}
function showStaff(i){const s=staff[i];$('#detail-content').innerHTML=`<div class="detail-layout"><div class="photo p${s.photo}" role="img" aria-label="${s.name}の架空のスタッフ写真"></div><div class="detail-copy"><p class="eyebrow">STYLIST / AMI</p><h2>${s.name} <small>${s.ja}</small></h2><p>${s.description}</p><p>担当スタイル：${i===0?'Soft chestnut / Rose brown':'Airy beige'}</p><button class="button dark" id="staff-select">${s.name}を指名して予約する <span>↗</span></button><small>スタッフ名・プロフィールは仮設定、写真はAI生成です。</small></div></div>`;openDialog($('#detail-dialog'));$('#staff-select').onclick=()=>{selectedStaff=i;$('#detail-dialog').close();openBooking();};}$$('[data-staff]').forEach(b=>b.onclick=()=>showStaff(Number(b.dataset.staff)));
const questions=[{title:'今、なりたい印象は？',options:['自然体で、柔らかく','軽やかで、洗練された感じ','ほんのり甘く、華やかに']},{title:'好きな色のムードは？',options:['温かみのあるブラウン','透明感のあるベージュ','血色を感じるローズ']},{title:'カラーを選ぶとき、大切なのは？',options:['普段の服になじむこと','さりげなく雰囲気を変えること','ちょっと気分が上がること']}];
let answers=[],quizStep=0,resultIndex=0;
function renderQuiz(){if(quizStep===3){const counts=[0,0,0];answers.forEach(i=>counts[i]++);resultIndex=counts.indexOf(Math.max(...counts));renderResult();return;}$('#quiz-content').innerHTML=`<div class="fade-enter"><p class="quiz-number">0${quizStep+1}<span style="font-size:14px"> / 03</span></p><h3 class="quiz-question">${questions[quizStep].title}</h3><div class="quiz-options">${questions[quizStep].options.map((o,i)=>`<button class="quiz-option" data-answer="${i}"><span>${String.fromCharCode(65+i)}</span>${o}<span>↗</span></button>`).join('')}</div><div class="quiz-footer"><span>あなたの気分で選んでください</span>${quizStep?'<button id="quiz-back">ひとつ戻る</button>':'<span>COLOR CONSULTATION</span>'}</div></div>`;$$('[data-answer]').forEach(b=>b.onclick=()=>{answers[quizStep]=Number(b.dataset.answer);quizStep++;renderQuiz();if(quizStep<3)$('#quiz-content .quiz-option').focus({preventScroll:true});});if($('#quiz-back'))$('#quiz-back').onclick=()=>{quizStep--;renderQuiz();};}
function renderResult(){const s=styles[resultIndex];$('#diagnosis').style.background=s.color;$('#quiz-content').innerHTML=`<div class="quiz-result"><p class="eyebrow">YOUR COLOR INSPIRATION</p><div class="photo p${resultIndex} result-photo-change" role="img" aria-label="${s.ja}の参考写真"></div><h3>${s.name}</h3><p>${s.mood}<br>${['自然な温かみを好むあなたへ。肌なじみを意識した、柔らかなブラウンをご提案。','軽やかさを楽しみたいあなたへ。落ち着いた透明感を感じるベージュをご提案。','気分を少し華やかにしたいあなたへ。さりげない甘さのあるローズをご提案。'][resultIndex]}</p><div class="swatches" role="group" aria-label="別の色も試す">${styles.map((x,i)=>`<button class="swatch ${i===resultIndex?'active':''}" style="--swatch:${x.swatch}" data-color="${i}" aria-label="${x.ja}を表示" aria-pressed="${i===resultIndex}"><span class="swatch-dot" aria-hidden="true"></span><span class="swatch-label">${x.ja}</span><span class="swatch-check" aria-hidden="true">${i===resultIndex?"✓ 選択中":""}</span></button>`).join('')}</div><p class="result-note">質問に基づくデモ提案です。写真は色の参考イメージです。</p><button class="button dark" id="quiz-book">このカラーで相談する <span>↗</span></button><button class="quiz-restart" id="quiz-restart">もう一度診断する</button></div>`;$$('[data-color]').forEach(b=>b.onclick=()=>{resultIndex=Number(b.dataset.color);renderResult();$(`[data-color="${resultIndex}"]`).focus({preventScroll:true});});$('#quiz-restart').onclick=()=>{answers=[];quizStep=0;$('#diagnosis').style.background='';renderQuiz();};$('#quiz-book').onclick=()=>{selectedStyle=resultIndex;selectedStaff=styles[resultIndex].staff;selectedMenu=0;renderMenus();updateQuote();toast(styles[resultIndex].ja+'を選択しました');openBooking();};}
renderQuiz();
let bookingStep=0,booking={staff:-1,date:'',time:'',name:'',email:''};
const tokyoDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function dateAfter(days){const d=new Date(tokyoDate()+'T12:00:00+09:00');d.setUTCDate(d.getUTCDate()+days);return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);}
const minDate=dateAfter(1),maxDate=dateAfter(60);
function dateLabel(date){return new Intl.DateTimeFormat('ja-JP',{timeZone:'Asia/Tokyo',month:'long',day:'numeric',weekday:'short'}).format(new Date(date+'T12:00:00+09:00'));}
function isTuesday(date){return new Date(date+'T12:00:00+09:00').getUTCDay()===2;}
function staffLabel(){return booking.staff===-1?'指名なし':staff[booking.staff].name;}
function summary(){const q=getQuote();return `<div class="book-summary"><div class="book-summary-details"><span class="book-summary-title">${menus[selectedMenu].name}</span>${selectedStyle!==null?'<span>参考スタイル：'+styles[selectedStyle].ja+'</span>':''}<span>${$('#hair-length').selectedOptions[0].textContent}</span><span>集中トリートメント：${$('#treatment').checked?'追加する（＋¥3,300 / 20分）':'追加なし'}</span></div><div class="book-summary-price"><small>税込合計</small><strong>${yen(q.price)}</strong><span>約${q.time}分</span></div></div>`;}
function bookingCustomization(){return `<fieldset class="booking-customization"><legend>長さ・追加ケアもここで変更できます</legend><label class="field" for="booking-length">髪の長さ<select id="booking-length">${[...$('#hair-length').options].map(o=>`<option value="${o.value}" ${o.selected?'selected':''}>${o.textContent}</option>`).join('')}</select></label><label class="check-option"><input type="checkbox" id="booking-treatment" ${$('#treatment').checked?'checked':''}>集中トリートメント <span>＋¥3,300 / 20分</span></label></fieldset>`;}
function refreshBookingQuote(){updateQuote();let timeCleared=false;if(booking.time&&Number(booking.time.split(':')[0])*60+getQuote().time>19*60){booking.time='';timeCleared=true;}$('#booking-summary').innerHTML=summary();const q=getQuote();$('#booking-quote-status').textContent='税込合計 '+yen(q.price)+'、約'+q.time+'分。'+(timeCleared?'施術時間が変わったため、ご希望の時間を選び直してください。':'');}
function openBooking(){bookingStep=0;booking.staff=selectedStaff;renderBooking();openDialog($('#booking-dialog'));}$$('[data-book]').forEach(b=>b.onclick=openBooking);$('#menu-book').onclick=openBooking;
function renderBooking(){const dialog=$('#booking-dialog');$('#booking-progress').innerHTML=bookingStep<4?`<div class="booking-steps" aria-label="予約の進行状況">${['内容・担当','日時','お客様情報','確認'].map((n,i)=>`<span class="${i<=bookingStep?'active':''}" ${i===bookingStep?'aria-current="step"':''}>0${i+1} ${n}</span>`).join('')}</div>`:'';let html='';
 if(bookingStep===0){html=`<h3 class="booking-content-title">メニューと担当を選ぶ</h3><label class="field">施術メニュー<select id="booking-menu">${menus.map((m,i)=>`<option value="${i}" ${i===selectedMenu?'selected':''}>${m.name} / ${yen(m.price)}〜</option>`).join('')}</select></label>${bookingCustomization()}<div id="booking-summary">${summary()}</div><p class="visually-hidden" id="booking-quote-status" role="status" aria-live="polite" aria-atomic="true"></p><p class="book-note">長さ・追加ケアを変えると、合計料金と所要時間が更新されます。</p><p class="field">担当スタッフ</p><div class="staff-options">${[-1,0,1].map(i=>`<button class="staff-option ${booking.staff===i?'active':''}" data-book-staff="${i}" aria-pressed="${booking.staff===i}">${i<0?'<span>✳</span>':`<div class="photo p${staff[i].photo}"></div>`}${i<0?'指名なし':staff[i].name}</button>`).join('')}</div><div class="booking-actions"><button class="button dark" id="booking-next">日時を選ぶ <span>→</span></button></div>`;}
 if(bookingStep===1){html=`<h3 class="booking-content-title">ご希望の日時</h3><label class="field">ご来店日（明日から60日先まで）<input type="date" id="booking-date" min="${minDate}" max="${maxDate}" value="${booking.date}" required></label><p class="time-caption">火曜日は定休日です。空き枠はデモ表示です。</p><div id="time-options"></div><p id="booking-error" class="booking-error" role="alert"></p><div class="booking-actions"><button class="button outline" id="booking-back">戻る</button><button class="button dark" id="booking-next">お客様情報へ <span>→</span></button></div>`;}
 if(bookingStep===2){html=`<h3 class="booking-content-title">お客様情報</h3><p class="book-note">デモです。架空のお名前・メールアドレスでお試しください。入力内容は外部に送信・保存されません。</p><form id="customer-form"><label class="field">お名前（必須）<input id="customer-name" name="name" required maxlength="60" autocomplete="off" placeholder="例：山田 はな" value="${escapeHTML(booking.name)}"></label><label class="field">メールアドレス（必須）<input id="customer-email" name="email" type="email" required maxlength="100" autocomplete="off" placeholder="例：demo@example.com" value="${escapeHTML(booking.email)}"></label><div class="booking-actions"><button class="button outline" type="button" id="booking-back">戻る</button><button class="button dark" type="submit">予約内容を確認 <span>→</span></button></div></form>`;}
 if(bookingStep===3){html=`<h3 class="booking-content-title">ご予約内容の確認</h3>${summary()}<dl class="confirm-list"><div><dt>日時</dt><dd>${dateLabel(booking.date)} ${booking.time}〜</dd></div><div><dt>スタッフ</dt><dd>${staffLabel()}</dd></div><div><dt>お名前</dt><dd>${escapeHTML(booking.name)}</dd></div><div><dt>メール</dt><dd>${escapeHTML(booking.email)}</dd></div></dl><p class="book-note">「デモ予約を完了」で体験が完了します。店舗への送信やメール配信、決済は行いません。</p><div class="booking-actions"><button class="button outline" id="booking-back">戻る</button><button class="button dark" id="booking-next">デモ予約を完了 <span>↗</span></button></div>`;}
 if(bookingStep===4){html=`<div class="success"><div class="success-mark">✓</div><p class="eyebrow">SEE YOU, NEW YOU.</p><h3>ご予約の体験が完了しました。</h3><p>${escapeHTML(booking.name)}さま<br>新しいスタイルに出会う、素敵なひとときを。</p>${summary()}<p>${dateLabel(booking.date)} ${booking.time}〜<br>担当：${staffLabel()}</p><p class="book-note">これはデモです。実際のご予約は成立していません。<br>メールの送信・決済も行っていません。</p><button class="button dark" id="booking-done">サイトに戻る <span>↗</span></button></div>`;}
 $('#booking-content').innerHTML=html;dialog.scrollTop=0;
 if($('#booking-menu'))$('#booking-menu').onchange=e=>{selectedMenu=Number(e.target.value);renderMenus();refreshBookingQuote();};
 if($('#booking-length'))$('#booking-length').onchange=e=>{$('#hair-length').value=e.target.value;refreshBookingQuote();};
 if($('#booking-treatment'))$('#booking-treatment').onchange=e=>{$('#treatment').checked=e.target.checked;refreshBookingQuote();};
 $$('[data-book-staff]').forEach(b=>b.onclick=()=>{booking.staff=Number(b.dataset.bookStaff);selectedStaff=booking.staff;$$('[data-book-staff]').forEach(x=>{const active=x===b;x.classList.toggle('active',active);x.setAttribute('aria-pressed',String(active));});});
 if(bookingStep===1){renderTimes();$('#booking-date').onchange=e=>{booking.date=e.target.value;booking.time='';renderTimes();};}
 if($('#booking-back'))$('#booking-back').onclick=()=>{if(bookingStep===2)saveCustomer();bookingStep--;renderBooking();};
 if($('#customer-form'))$('#customer-form').onsubmit=e=>{e.preventDefault();saveCustomer();if(!booking.name.trim()){ $('#customer-name').setCustomValidity('お名前を入力してください。');$('#customer-name').reportValidity();return;}bookingStep=3;renderBooking();};
 if($('#customer-name'))$('#customer-name').oninput=()=>$('#customer-name').setCustomValidity('');
 if($('#booking-next'))$('#booking-next').onclick=()=>{if(bookingStep===1){const message=validateDate();if(message){$('#booking-error').textContent=message;return;}}bookingStep++;renderBooking();};
 if($('#booking-done'))$('#booking-done').onclick=()=>{dialog.close();booking.name='';booking.email='';booking.date='';booking.time='';};
}
function saveCustomer(){booking.name=$('#customer-name').value.trim();booking.email=$('#customer-email').value.trim();}
function validateDate(){if(!booking.date||booking.date<minDate||booking.date>maxDate)return '明日から60日先までの日付を選んでください。';if(isTuesday(booking.date))return '火曜日は定休日です。別の日をお選びください。';if(!booking.time)return 'ご希望の時間を選んでください。';const hour=Number(booking.time.split(':')[0]);if(hour===12||hour<10||hour*60+getQuote().time>19*60)return 'このメニューで選択できる時間を選び直してください。';return '';}
function renderTimes(){const host=$('#time-options');if(!booking.date){host.innerHTML='<p class="book-note">日付を選ぶと、時間が表示されます。</p>';return;}if(booking.date<minDate||booking.date>maxDate){host.innerHTML='<p class="booking-error">受付期間内の日付を選んでください。</p>';return;}if(isTuesday(booking.date)){host.innerHTML='<p class="booking-error">この日は定休日です。別の日をお選びください。</p>';return;}const q=getQuote();const times=['10:00','11:00','12:00','13:00','14:00','15:00','16:00','17:00','18:00'].filter(t=>Number(t.split(':')[0])*60+q.time<=19*60);host.innerHTML=`<div class="time-grid" role="group" aria-label="ご希望の時間">${times.map((t,i)=>`<button data-time="${t}" class="${booking.time===t?'active':''}" aria-pressed="${booking.time===t}" ${i===2?'disabled':''}>${t} ${i===2?'×':'○'}</button>`).join('')}</div>`;$$('[data-time]').forEach(b=>b.onclick=()=>{booking.time=b.dataset.time;$('#booking-error').textContent='';renderTimes();});}
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target);}}),{threshold:.08});$$('.reveal').forEach(el=>observer.observe(el));}else{$$('.reveal').forEach(el=>el.classList.add('visible'));}
